// the array parameter is really a pointer: the two headers are the same
void f(int a[], int n);
void f(int *a, int n);

// read-only: the function cannot change the array
int sumArray(const int a[], int n);

// can change the original array
void fillArray(int a[], int n, int value);

int data[5] = {4, 9, 2, 7, 5};
sumArray(data, 5);        // call: name only, no [ ] and no &
fillArray(data, 5, 0);    // data is now all zeros

// inside a function: a[i] and *(a + i) both work

sample.code:
#include <iostream>
using namespace std;

int sumArray(const int a[], int n) {
    int s = 0;
    for (int i = 0; i < n; i++) {
        s += a[i];
    }
    return s;
}

int main() {
    int marks[4] = {70, 80, 90, 60};
    cout << "Sum = " << sumArray(marks, 4) << endl;
    return 0;
}

#include <iostream>
using namespace std;

void printArray(const int a[], int n) {
    for (int i = 0; i < n; i++) {
        cout << a[i] << " ";
    }
    cout << endl;
}

void doubleAll(int a[], int n) {
    for (int i = 0; i < n; i++) {
        a[i] = a[i] * 2;
    }
}

int main() {
    int data[3] = {1, 2, 3};
    printArray(data, 3);
    doubleAll(data, 3);
    printArray(data, 3);
    return 0;
}

#include <iostream>
using namespace std;

int maxArray(const int a[], int n) {
    int m = a[0];
    for (int i = 1; i < n; i++) {
        if (a[i] > m) {
            m = a[i];
        }
    }
    return m;
}

void reverseArray(int a[], int n) {
    for (int i = 0; i < n / 2; i++) {
        int t = a[i];
        a[i] = a[n - 1 - i];
        a[n - 1 - i] = t;
    }
}

void fillArray(int a[], int n, int value) {
    for (int i = 0; i < n; i++) {
        a[i] = value;
    }
}

int main() {
    int a[5] = {4, 9, 2, 7, 5};
    cout << "Max = " << maxArray(a, 5) << endl;
    reverseArray(a, 5);
    cout << a[0] << " " << a[1] << " " << a[2] << " " << a[3] << " " << a[4] << endl;
    fillArray(a, 5, 0);
    cout << a[0] << " " << a[4] << endl;
    return 0;
}

